def load() -> pd.DataFrame:
    with open('data/astronomy/input/TLE/48445.tle', 'r') as f:
        lines = f.readlines()
    rows = []
    for i, line in enumerate(lines):
        rows.append({'line_num': i, 'content': line.strip()})
    return pd.DataFrame(rows)

def process(load_tle) -> pd.DataFrame:
    lines = load_tle['content'].tolist()
    records = []
    i = 0
    while i < len(lines) - 1:
        l1 = lines[i].strip()
        l2 = lines[i+1].strip()
        if l1.startswith('1 ') and l2.startswith('2 '):
            records.append({'line1': l1, 'line2': l2})
            i += 2
        else:
            i += 1
    return pd.DataFrame(records)

def process(compute_altitudes) -> pd.DataFrame:
    df = compute_altitudes[['epoch_tt', 'epoch_utc', 'altitude_km']].drop_duplicates().sort_values('epoch_tt').reset_index(drop=True)

    # epoch_tt is Julian Day (TT), 1 day = 1.0 unit; 12h = 0.5 units
    half_day = 0.5
    threshold_km = 1.0  # 1000m = 1 km

    epochs = df['epoch_tt'].values
    alts = df['altitude_km'].values

    change_count = 0
    n = len(df)

    for i in range(n):
        for j in range(i + 1, n):
            dt = epochs[j] - epochs[i]
            if dt > half_day:
                break  # sorted, no need to go further
            delta_alt = abs(alts[j] - alts[i])
            if delta_alt > threshold_km:
                change_count += 1

    return pd.DataFrame({
        'total_major_altitude_changes': [change_count],
        'threshold_km': [threshold_km],
        'window_hours': [12],
        'total_tle_epochs': [n]
    })
